def summarize_ranges(nums: list[int]) -> str:
    unique = sorted(set(nums))
    if not unique:
        return ""

    parts = []
    i = 0
    n = len(unique)

    while i < n:
        start = unique[i]
        end = start
        j = i + 1

        while j < n and unique[j] == end + 1:
            end = unique[j]
            j += 1

        length = end - start + 1

        if length >= 3:
            parts.append(f"{start}..{end}")
        elif length == 2:
            parts.append(f"{start},{end}")
        else:
            parts.append(f"{start}")

        i = j

    return ",".join(parts)
